    if (!BACKEND_TO_MODE[state] && !warnedStatus[state]) { warnedStatus[state] = 1; console.warn('[status] unknown backend status "' + state + '" -> showing idle'); }
    if (next === 'idle' && modeName !== 'idle') idleSince = Date.now();
