  const MUTE_ICON_OFF = '<svg viewBox="0 0 24 24"><path d="M4 9v6h4l5 5V4L8 9H4z"/><path class="mute-x" d="M15.2 9.2l4.6 4.6M19.8 9.2l-4.6 4.6"/></svg>';
